static int isr_adapter_func(int irq, FAR void *context, FAR void *arg)
{
  FAR struct intr_adapter_to_nuttx *isr_adapter_args =
    (FAR struct intr_adapter_to_nuttx *)arg;

  isr_adapter_args->handler(isr_adapter_args->arg);

  return 0;
}

